from __future__ import annotations

from datetime import date

import polars as pl
from src.backtest.strategy import MarketView, Signal, Strategy


class LiquidityScreenedEqualWeighting(Strategy):
    rationale = (
        "Higher liquidity stocks are often more efficient in price discovery and trading. "
        "By equal-weighting these liquid stocks, the strategy can benefit from reduced "
        "slippage and higher market impact."
    )

    def __init__(self, window: int = 30) -> None:
        self._window = window

    def generate(self, view: MarketView) -> Signal:
        stamp = _latest_visible(view)
        history = view.history(lookback=self._window)
        if history.is_empty():
            return Signal(information_available_at=stamp, weights={})

        liquidity_screened_symbols = (
            history.select(pl.col("symbol"))
            .group_by("symbol")
            .agg(
                (pl.col("volume").mean() / pl.col("volume").std()).alias("liquidity_score")
            )
            .sort("liquidity_score", descending=True)
            .head(self._window)["symbol"]
            .to_list()
        )

        if not liquidity_screened_symbols:
            return Signal(information_available_at=stamp, weights={})

        weight = 1.0 / len(liquidity_screened_symbols)
        return Signal(
            information_available_at=stamp, weights={s: weight for s in liquidity_screened_symbols}
        )


def _latest_visible(view: MarketView) -> date:
    visible = view.history()
    if visible.is_empty():
        return date(1900, 1, 1)
    newest = visible["session_date"].max()
    assert isinstance(newest, date)
    return newest
